        QString someString;
        explicit Thread(QThreadStorage<SPointer> &t1, QThreadStorage<QString> &t2,
                        QThreadStorage<int> &t3, QThreadStorage<std::unique_ptr<int>> &t4)
            : tlsSPointer(t1), tlsString(t2), tlsInt(t3), tlsUniquePtr(t4) { }

